using System;
public static class LifeRulesTests {
 static int Checks;static void Check(bool ok,string name){if(!ok)throw new Exception(name);Checks++;}
 public static void Main(){var life=new CoopLifeRules();life.Reset(100,80);Check(life.Health[0]==100&&life.Health[1]==80,"independent maximums");life.Health[1]=0;Check(!life.Defeated,"one down is not a team defeat");life.Health[0]=60;Check(life.Rescue(0),"first rescue allowed");Check(life.Health[0]==30&&life.Health[1]==30,"exact half current health transferred");Check(life.Rescued[1]&&!life.Rescued[0],"limit belongs to recipient");life.Health[1]=0;float donor=life.Health[0];Check(!life.Rescue(0)&&life.Health[0]==donor,"second rescue forbidden without spending donor health");life.Heal(1,999);Check(life.Down(1),"healing cannot bypass the rescue limit");life.Health[0]=0;Check(life.Defeated,"both down end the run");life.Reset(100,100);life.Health[0]=0;life.Health[1]=1;Check(life.Rescue(1)&&life.Health[0]==0.5f&&life.Health[1]==0.5f,"fractional health is conserved");life.Health[1]=0;Check(life.Rescue(0)&&life.Health[0]==0.25f&&life.Health[1]==0.25f,"each player may be rescued once");life.Reset(100,10);life.Health[1]=0;Check(life.Rescue(0)&&life.Health[0]==50&&life.Health[1]==10,"recipient cap does not discount the donor cost");life.Health[1]=0;life.SetMaximum(1,50);Check(life.Down(1),"maximum health growth cannot resurrect a corpse");life.Reset(10,10);life.SetMaximum(0,20);Check(life.Health[0]==20&&life.Health[1]==10,"health growth remains individual");var roles=new ControllerRoles();roles.Update(new[]{1,2},true);roles.Update(new[]{2},true);Check(roles.First==-1&&roles.Second==2,"survivor retains their slot after disconnect");roles.Update(new[]{3,2},true);Check(roles.First==3&&roles.Second==2,"replacement occupies the vacant slot");Console.WriteLine("PASS: "+Checks+" individual-life, rescue and stable-role checks");}
}
